"""Which free source can SEARCH for what - and the three dates a found document carries.

Every adapter in this library fetches by identifier: `bars("AAPL")`, `macro("DGS10")`,
`fundamentals("0000320193")`. That is the second half of the job. The first half is
finding the identifier, and an agent that guesses one is worse off than an agent that
stops: `DGS10` and `DGS10YR` are both plausible, one of them exists, and the wrong guess
comes back as an empty frame rather than an error.

Two tables live here.

  * `SOURCES` - the free, documented search endpoints, each declaring what its free text
    is matched AGAINST and, more usefully, what it cannot do. The `cannot` column is the
    one to read: three of the four cannot answer "as of a past date" at all, so a universe
    built from them is a current snapshot wearing a historical label.
  * `document_dates()` - a found document has THREE dates and they are not
    interchangeable. Feed it rows shaped like the SEC Submissions API's `filings.recent`
    and it returns all three plus the availability the data layer actually keys on.

Offline, seeded, no writes. The fixture is Apple's own filing metadata, copied verbatim
from data.sec.gov; the counts printed at the bottom are computed from it.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Mapping, Sequence

import pandas as pd

EXCHANGE_TZ = "America/New_York"
CLOSE_HOUR = 16


@dataclass(frozen=True)
class Source:
    """One searchable source, and the sentence that keeps you from misusing it."""

    name: str
    endpoint: str
    searches: str            # what the free text is matched against
    returns: str             # the identifier scheme you get back
    credential: str          # what you must supply, and whether it can be shared
    rate_limit: str
    as_of: str               # can it answer about a PAST date?
    cannot: tuple[str, ...]


