#: plain-English need -> the sources that can actually answer it
ROUTES: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("a macro series id", ("fred_series_search",)),
    ("a company's CIK from its ticker", ("sec_company_tickers",)),
    ("a ticker from a company name", ("sec_company_tickers",)),
    ("a filing that mentions a phrase", ("sec_full_text_search",)),
    ("a crypto pair or perpetual symbol", ("ccxt_markets",)),
    ("a delisted company", ()),
    ("a futures contract code", ()),
    ("the ticker a CIK used in 2008", ()),
)


def where_to_search(need: str) -> tuple[str, ...]:
    """Sources that can answer `need`, or an empty tuple - which is also an answer."""
    key = str(need).strip().lower()
    if not key:
        return ()                 # an empty need matches everything, which helps nobody
    for label, names in ROUTES:
        if label.lower() == key:
            return names
    hits = tuple(n for label, names in ROUTES if key in label.lower() for n in names)
    return tuple(dict.fromkeys(hits))


def source_table() -> pd.DataFrame:
    return pd.DataFrame([{"source": s.name, "searches": s.searches, "returns": s.returns,
                          "as_of": s.as_of, "cannot": len(s.cannot)} for s in SOURCES])


# --------------------------------------------------------------- the three document dates
def document_dates(filings: Iterable[Mapping], *, tz: str = EXCHANGE_TZ,
                   close_hour: int = CLOSE_HOUR) -> pd.DataFrame:
    """The three dates of each document, plus the one a backtest may key on.

    period_end       what the document COVERS. Months before it exists. Using it is the
                     30-90 day look-ahead that fundamental studies are famous for.
    filed_at         the date EDGAR stamps, assigned by its own cutoff rules. Off by a
                     day in both directions from the moment the document appeared.
    acceptance_at    the wall-clock instant it became public. The truth, and the only one
                     of the three that is an instant rather than a date.
    available_at     the first session it could be traded on: acceptance converted to
                     exchange-local, rolled to the next session when it lands at or after
                     the close. This is the column to join on.
    """
    rows = []
    for f in filings:
        acc = pd.Timestamp(f["acceptanceDateTime"])
        acc = acc.tz_localize("UTC") if acc.tz is None else acc.tz_convert("UTC")
        local = acc.tz_convert(tz)
        post_close = local.hour >= close_hour
        avail = local.normalize().tz_localize(None) + pd.Timedelta(days=1 if post_close else 0)
        while avail.weekday() >= 5:              # no holiday calendar here: pass one in
            avail += pd.Timedelta(days=1)
        filed = pd.Timestamp(f["filingDate"])
        period = pd.to_datetime(f.get("reportDate") or None, errors="coerce")
        rows.append({"accession": f.get("accessionNumber", ""), "form": f.get("form", ""),
                     "period_end": period, "filed_at": filed,
                     "acceptance_local": local.tz_localize(None),
                     "post_close": post_close, "available_at": avail,
                     "period_lag_days": (filed - period).days if pd.notna(period) else -1,
                     "filed_matches_acceptance":
                         filed.normalize() == local.normalize().tz_localize(None)})
    return pd.DataFrame(rows)


#: forms whose reportDate is a fiscal PERIOD end. An 8-K's reportDate is an event date,
#: so pooling the two makes the period-to-filing lag meaningless.
PERIODIC_FORMS = ("10-K", "10-Q", "20-F", "40-F", "10-K/A", "10-Q/A")


def lookahead_summary(dates: pd.DataFrame,
                      periodic: Sequence[str] = PERIODIC_FORMS) -> dict:
    """How much of a document set each shortcut would have bought you for free."""
    n = len(dates)
    if not n:
        return {"n": 0}
    per = dates[(dates["period_lag_days"] >= 0) & dates["form"].isin(tuple(periodic))]
    return {
        "n_periodic": len(per),
        "n": n,
        "post_close": int(dates["post_close"].sum()),
        "post_close_pct": 100.0 * dates["post_close"].sum() / n,
        "filed_disagrees_with_acceptance": int((~dates["filed_matches_acceptance"]).sum()),
        "same_day_post_close": int((dates["post_close"]
                                    & dates["filed_matches_acceptance"]).sum()),
        "median_period_lag_days": float(per["period_lag_days"].median()) if len(per) else float("nan"),
        "max_period_lag_days": int(per["period_lag_days"].max()) if len(per) else -1,
    }


